TLM.f("Sancti/12-25m2",{"officium":"In Nativitatis Domini in aurora","rule":["Gloria","Credo","Prefatio=Nat","celebranda aut missa prima aut missa secunda aut missa tertia"],"sections":{"Introitus":[{"k":"ref","la":"Is 9:2 et 6"},{"k":"text","la":"Lux fulgébit hódie super nos: quia natus est nobis Dóminus: et vocábitur Admirábilis, Deus, Princeps pacis, Pater futúri sǽculi: cujus regni non erit finis."},{"k":"ref","la":"Ps 92:1"},{"k":"text","la":"Dóminus regnávit, decórem indútus est: indútus est Dóminus fortitúdinem, et præcínxit se."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Lux fulgébit hódie super nos: quia natus est nobis Dóminus: et vocábitur Admirábilis, Deus, Princeps pacis, Pater futúri sǽculi: cujus regni non erit finis."}],"Oratio":[{"k":"text","la":"Da nobis, quǽsumus, omnípotens Deus: ut, qui nova incarnáti Verbi tui luce perfúndimur; hoc in nostro respléndeat ópere, quod per fidem fulget in mente."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Titum"},{"k":"ref","la":"Tit 3:4-7"},{"k":"text","la":"Caríssime: Appáruit benígnitas et humánitas Salvatóris nostri Dei: non ex opéribus justítiæ, quæ fécimus nos, sed secúndum suam misericórdiam salvos nos fecit, per lavácrum regeneratiónis et renovatiónis Spíritus Sancti, quem effúdit in nos abúnde per Jesum Christum, Salvatórem nostrum: ut, justificáti grátia ipsíus, herédes simus secúndum spem vitæ ætérnæ: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 117:26; 117:27; 117:23"},{"k":"text","la":"Benedíctus, qui venit in nómine Dómini: Deus Dóminus, et illúxit nobis."},{"k":"text","la":"A Dómino factum est istud: et est mirábile in óculis nostris.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 92:1"},{"k":"text","la":"Dóminus regnávit, decórem índuit: índuit Dóminus fortitúdinem, et præcínxit se virtúte. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 2:15-20"},{"k":"text","la":"In illo témpore: Pastóres loquebántur ad ínvicem: Transeámus usque Béthlehem, et videámus hoc verbum, quod factum est, quod Dóminus osténdit nobis. Et venérunt festinántes, et invenérunt Maríam, et Joseph, et Infántem pósitum in præsépio. Vidéntes autem cognovérunt de verbo, quod dictum erat illis de Púero hoc. Et omnes, qui audiérunt, miráti sunt: et de his, quæ dicta erant a pastóribus ad ipsos. María autem conservábat ómnia verba hæc, cónferens in corde suo. Et revérsi sunt pastores, glorificántes et laudántes Deum in ómnibus, quæ audíerant et víderant, sicut dictum est ad illos."}],"Offertorium":[{"k":"ref","la":"Ps 92:1-2"},{"k":"text","la":"Deus firmávit orbem terræ, qui non commovébitur: paráta sedes tua, Deus, ex tunc, a sǽculo tu es."}],"Secreta":[{"k":"text","la":"Múnera nostra, quǽsumus, Dómine, Nativitátis hodiérnæ mystériis apta provéniant, et pacem nobis semper infúndant: ut, sicut homo génitus idem refúlsit et Deus, sic nobis hæc terréna substántia cónferat, quod divínum est."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"ref","la":"Zach 9:9"},{"k":"text","la":"Exsúlta, fília Sion, lauda, fília Jerúsalem: ecce, Rex tuus venit sanctus et Salvátor mundi."}],"Postcommunio":[{"k":"text","la":"Hujus nos, Dómine, sacraménti semper nóvitas natális instáuret: cujus Natívitas singuláris humánam réppulit vetustátem."},{"k":"macro","name":"Per eundem"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro S. Anastasiæ"},{"k":"text","la":"Da, quǽsumus, omnípotens Deus: ut, qui beátæ Anastásiæ Mártyris tuæ sollémnia cólimus; ejus apud te patrocínia sentiámus."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro S. Anastasia"},{"k":"text","la":"Accipe, quǽsumus, Dómine, múnera dignánter obláta: et, beátæ Anastásiæ Mártyris tuæ suffragántibus méritis, ad nostræ salútis auxílium proveníre concéde."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro S. Anastasia"},{"k":"text","la":"Satiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"415ad3ab0037d4f9":{"t":"Iz 9, 2 i 6, Ps 92, 1\n(Iz 9, 2 i 6) Danas zasja nad nama svjetlo, jer nam se rodio Gospodin. Ime mu je Divni, Bog, Knez mira, Otac budućega vijeka. Njegovu kraljevstvu neće biti kraja. (Ps 92, 1) Gospodin kraljuje, ogrnuo se veličanstvom, zaodio se Gospodin snagom i opasao se.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iz 9, 2 i 6) Danas zasja nad nama svjetlo, jer nam se rodio Gospodin. Ime mu je Divni, Bog, Knez mira, Otac budućega vijeka. Njegovu kraljevstvu neće biti kraja.","kn":"tJlaz (Izai. 9, 2-6), Svjetlost će danas zasjati nad nama, jer nam se rodi Gospodin. Ime je njegovo Divni, Bog, Vladar mira. Otac budućega vijeka. I njegovu kraljevstvu he će biti kraja. (Ps. 92, 1). Gospodin caruje okružen veličanstvom, odjeven jakošću i opasan snagom. Slava Ocu . . . Svjetlost . . .","knRef":"Kniewald 1942, str. 58–59 (snimka 30) (OCR)"},"b75c860b225ca08c":{"t":"<i>Pomolimo se</i>.\nObasjani novom svjetlošću utjelovljene tvoje Riječi daj molimo, svemogući Bože, da u našim djelima odsijeva ona svjetlost koja nam po vjeri sja u duši.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Daj nam, molimo Te, svemogući Bože, da nova svjetlost Tvoje utjelovljene PJječi, koja nas osvjetljuje, odsijeva i u našim djelima, kao što po vjeri sjaji u duši, po istom G. n. I. K.","knRef":"Kniewald 1942, str. 58–59 (snimka 30) (OCR)"},"b6aeaffed9caea31":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da mi koji slavimo svečanost blažene Anastazije, tvoje mučenice, osjetimo njezin zagovor kod tebe.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da mi, koji slavimo svečanost blažene Anastazije, mučenice Tvoje, osjetimo njezin zagovor kod Tebe, po G. n. I. K.","knRef":"Kniewald 1942, str. 58–59 (snimka 30) (OCR)"},"e0f30f9a6fa2333c":{"t":"Tit 3, 4-7\nČitanje Poslanice bl. Pavla apostola Titu. Predragi: objavila se dobrota i čovjekoljublje Boga našega Spasitelja. On nas je spasio, ali ne po našim pravednim djelima nego po svojem milosrđu, po kupelji preporoda i obnove Duha Svetoga. Njega je na nas obilno izlio po našem Spasitelju Isusu Kristu, da opravdani njegovom milošću budemo po ufanju baštinici vječnog života u našem Gospodinu Isusu Kristu.","kn":"Čitanje poslanice bi, Pavla apostola Titu (3, 4-7). Predragi! Objavila se dobrota i čovjekoljublje Spasitelja našega Boga. On nas je spasio, ali ne po pravednim djelima., što smo ih mi učinili, nego po svomu milosrđu, po kupelji preporoda i obnove Duha Svetoga., koijega je obilno na nas izlio po Božić — ■ danja misa Isusu Kristu Spasitelju našemu, da opravdani njegovom milošću, po ufanju budemo baštinici vječnoga života u Isusu Kristu, Gospodinu našemu.","knRef":"Kniewald 1942, str. 58–59 (snimka 30) (OCR)"},"878fd2c03483858f":{"t":"Ps 117, 26-27 i 23\nBlagoslovljen koji dolazi u ime Gospodnje. Bog je Gospodin i on nas je obasjao. Gospodin je to učinio, divan prizor u očima našim!\n\nPs 92, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nGospodin kraljuje, ogrnuo se veličanstvom, zaodio se Gospodin snagom i opasao se jakošću. <i>Aleluja</i>.","v":"∅ → a","kn":"(Ps, 117, 26, 23). Blagoslovljen, koji dolazi u ime Gospodnje! Gospodin je Bog, koji nas je obasjao. To je učinio Gospodin i divno je u očima našim, Aleluja, Aleluja. (Ps. 92,- 1) Gospođin caruje okružen veličanstvom, odjeven jakošću i opasan snagom. Aleluja.","knRef":"Kniewald 1942, str. 60–61 (snimka 31) (OCR)"},"87d338e1955655ec":{"t":"Lk 2, 15-20\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: pozovu pastiri jedan drugoga: »Pođimo u Betlehem da vidimo što se dogodilo, kako nam je objavio Gospodin!« Pođu žurno i nađu Mariju i Josipa i Dijete položeno u jasle. Kad su vidjeli, shvatili su što im je rečeno o tom Djetetu. Svi koji su čuli, divili su se onome što su im kazivali pastiri. Sve je te riječi Marija pamtila razmišljajući u svom srcu. A pastiri se vrate slaveći Boga za sve što su čuli i vidjeli, kako im je bilo rečeno.","kn":"t Slijedi sveto Evanđelje po Luki (2, 15-20). U ono vrijeme rekoše pastiri jedan drugome: Pođimo do Betlehema, da vidimo, što ee dogodilo, kako nam je objavio Gospodin. Pođu žurno i nađu Mariju i Josipa i dijete, gdje leži u jaslama. I kad oni odu, vidješe, i uvjeriše se o tom, što im je bilo rečeno o ovom djetetu. I svi, koji su čuli, divili su se onomu, što su im kazivali pastiri. A Marija je sve ovo pamtila razmišljajući u svom srcu. I pastiri se povratiše slaveći Boga za sve, što su čuli i vidjeli, kako im je bilo kazano.","knRef":"Kniewald 1942, str. 60–61 (snimka 31) (OCR)"},"04fc59c226e81717":{"t":"Ps 92, 1-2\nBog je učvrstio zemaljski krug. koji se neće pokolebati. Otada je pripravno prijestolje tvoje. Bože, Ti si od vijeka.","kn":"_(Ps. 92, 1-2). Bog je utvrdio krug zemaljski i ,ne će se uekolebati. Tvoj je prijesto. Gospodine, od vijeka, a Ti si vječan","knRef":"Kniewald 1942, str. 66–67 (snimka 34) (OCR)"},"fc552dddb1f07247":{"t":"Naši darovi, molimo, Gospodine, neku, postanu prikladni današnjem božićnom otajstvu i neka nam vazda ulijevaju mir, kao što je isti čovjek koji je rođen zasjao i kao Bog, tako neka nam i ova zemaljska dobra pribave što je božansko.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":", Molimo, Gospodine, da naši darovi budu prikladni tajnama današnjeg Rođenja i da nam uvijek ulijevaju mir, te kao što je isti čovjek,- koji je danas rođen, zasjao i kao Bog, tako da nam ova zemaljska bit udijeli ono, što je božanske, po istom G. n. I. K.","knRef":"Kniewald 1942, str. 60–61 (snimka 31) (OCR)"},"3b91524186030199":{"t":"Primi, molimo, Gospodine, darove tebi na čast prinesene i podaj da po zaslugama blažene Anastazije budu na pomoć našemu spasenju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, molimo Te, Gospodine, darove, što Ti se dostojno prinose i dopusti, da zagovorom zasluga blažene Anastazije, mučenice Tvoje, promiču naše spasenje, po G. n. t. K.","knRef":"Kniewald 1942, str. 60–61 (snimka 31) (OCR)"},"46276ff06c5f858a":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine sveti Oče, svemogući i vječni Bože: jer je po tajni utjelovljene Riječi očima naše duše sinula nova svjetlost tvoga sjaja. Te dok tjelesnim očima spoznajemo Boga, on nas zanosi ljubavlju prema nevidljivim dobrima. I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, jer je otajstvom utjelovljene Riječi očima naše duše zasjalo novo svijetlo Tvoje sjajnosti, te nas Bog, dok ga spoznajemo u vidljivom obličju, privlači da ljubimo i nevidljive stvari. I zato pjevamo pjesmu slave Tvoje s anđelima i arkanđelima, s prijestolima 1 s gospodstvima, sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"3698267fc9268fe8":{"t":"Zah 9, 9\nKliči, narode sionski, pjevaj, Jeruzaleme, evo kralj ti dolazi, svet. Spasitelj svijeta.","kn":"(Zah. 9, 9). Kliči, kćeri sionska, pjevaj kćeri Jeruzalemska, evo dolazi Kralj tvoj, sveti, spasitelj, svijeta.","knRef":"Kniewald 1942, str. 60–61 (snimka 31) (OCR)"},"59a1f8900a70538e":{"t":"<i>Pomolimo se</i>.\nNeka nas, Gospodine, uvijek obnavlja ovim otajstvom novi rođendan tvojega Sina, jer je njegovo jedinstveno rođenje potisnulo ono staro u ljudima.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"; Božična nas. Gospodine, novina ovih tajna uvijek obnavljala, jer je jedinstveno rođenje Sina Tvoga iz čovječanstva odagnalo starinu grijeha, po istom G. n. I. K.","knRef":"Kniewald 1942, str. 60–61 (snimka 31) (OCR)"},"dfce8e9a1c23b4e0":{"t":"<i>Pomolimo se</i>.\nNasitio si, Gospodine, svoju obitelj svetim darovima, molimo da nas uvijek krijepiš na zagovor one čiju svečanost slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, pošto si nahranio svoju obitelj presvetim darovima, da nas uvijek krijepiš zagovorom one, koje blagdan slavimo, Po G. n.","knRef":"Kniewald 1942, str. 506–507 (snimka 254) (OCR)"}}});
